using System;
using System.Collections.Generic;
using System.Threading.Tasks;
class StreamAdapter {
  public async IAsyncEnumerable<T> Read<T>(IAsyncEnumerable<T> source, IAsyncDisposable resource) {
    await using (resource) {
      await foreach (var item in source) {
        yield return item;
      }
    }
  }
}

